beforeExample:
package test;
import org.eclipse.jdt.core.IParent;

public class MyClass {
    public void someMethod(Object parent) {
        if (parent instanceof IParent) {
            System.out.println("Is parent");
        }
    }
}

afterExample:
package test;
import org.eclipse.jdt.core.IParent;
import org.eclipse.jdt.core.IModuleDescription;

public class MyClass {
    public void someMethod(Object parent) {
        if (parent instanceof IParent && !(parent instanceof IModuleDescription)) {
            System.out.println("Is parent");
        }
    }
}

negativeExample:
package test;
import org.eclipse.jdt.core.ISourceReference;

public class MyClass {
    public void someMethod(Object element) {
        if (element instanceof ISourceReference) {
            System.out.println("Is source reference");
        }
    }
}
